CREATE TABLE `staff_attendance` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`attendance_date` text NOT NULL,`status` text DEFAULT 'present' NOT NULL,`check_in` text,`check_out` text,`late_minutes` integer DEFAULT 0 NOT NULL,`worked_minutes` integer,`source` text DEFAULT 'manual' NOT NULL,`notes` text,`recorded_by` text NOT NULL REFERENCES users(id),`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `staff_attendance_staff_date_uq` ON `staff_attendance` (`organization_id`,`staff_id`,`attendance_date`);
CREATE INDEX `staff_attendance_campus_date_idx` ON `staff_attendance` (`organization_id`,`campus_id`,`attendance_date`);
CREATE TABLE `staff_attendance_corrections` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`attendance_id` text NOT NULL REFERENCES staff_attendance(id) ON DELETE cascade,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`requested_status` text NOT NULL,`requested_check_in` text,`requested_check_out` text,`reason` text NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`requested_by` text NOT NULL REFERENCES users(id),`reviewed_by` text REFERENCES users(id),`reviewed_at` integer,`review_notes` text,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE INDEX `staff_attendance_corrections_queue_idx` ON `staff_attendance_corrections` (`organization_id`,`status`,`created_at`);
CREATE TABLE `leave_types` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`name` text NOT NULL,`code` text NOT NULL,`annual_allowance` real DEFAULT 0 NOT NULL,`is_paid` integer DEFAULT true NOT NULL,`requires_approval` integer DEFAULT true NOT NULL,`carry_forward` integer DEFAULT false NOT NULL,`status` text DEFAULT 'active' NOT NULL,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `leave_types_org_code_uq` ON `leave_types` (`organization_id`,`code`);
CREATE TABLE `staff_leave_balances` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`leave_type_id` text NOT NULL REFERENCES leave_types(id) ON DELETE cascade,`academic_year_id` text NOT NULL REFERENCES academic_years(id) ON DELETE restrict,`allocated_days` real DEFAULT 0 NOT NULL,`used_days` real DEFAULT 0 NOT NULL,`carried_forward_days` real DEFAULT 0 NOT NULL,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `staff_leave_balance_uq` ON `staff_leave_balances` (`organization_id`,`staff_id`,`leave_type_id`,`academic_year_id`);
CREATE TABLE `staff_leave_requests` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`leave_type_id` text NOT NULL REFERENCES leave_types(id) ON DELETE restrict,`academic_year_id` text NOT NULL REFERENCES academic_years(id) ON DELETE restrict,`starts_on` text NOT NULL,`ends_on` text NOT NULL,`total_days` real NOT NULL,`reason` text NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`requested_by` text NOT NULL REFERENCES users(id),`reviewed_by` text REFERENCES users(id),`reviewed_at` integer,`review_notes` text,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE INDEX `staff_leave_requests_queue_idx` ON `staff_leave_requests` (`organization_id`,`campus_id`,`status`,`starts_on`);
CREATE INDEX `staff_leave_requests_staff_idx` ON `staff_leave_requests` (`organization_id`,`staff_id`,`starts_on`,`ends_on`);
